import io
import sys

# Capture output
old_stdout = sys.stdout
sys.stdout = io.StringIO()

try:
    exec_globals = {}
    exec(code, exec_globals)
    output = sys.stdout.getvalue()
finally:
    sys.stdout = old_stdout

# Check if student1 exists
if 'student1' not in exec_globals:
    raise AssertionError('Step 6: student1 variable not found')

student1 = exec_globals['student1']

# Check class relationships
Person = exec_globals.get('Person')
Student = exec_globals.get('Student')

if not isinstance(student1, Student):
    raise AssertionError('student1 should be an instance of Student')
if not isinstance(student1, Person):
    raise AssertionError('student1 should also be an instance of Person (inheritance)')

# Check attributes
if not hasattr(student1, 'name'):
    raise AssertionError('student1 missing name attribute')
if not hasattr(student1, 'age'):
    raise AssertionError('student1 missing age attribute')
if not hasattr(student1, 'student_id'):
    raise AssertionError('student1 missing student_id attribute')

# Check attribute values
if student1.name != 'Jane Doe':
    raise AssertionError(f'student1.name should be "Jane Doe", got "{student1.name}"')
if student1.age != 20:
    raise AssertionError(f'student1.age should be 20, got {student1.age}')
if student1.student_id != 'S1234':
    raise AssertionError(f'student1.student_id should be "S1234", got "{student1.student_id}"')

# Check output
output_lower = output.lower()
if 'jane doe' not in output_lower:
    raise AssertionError('Output should include name "Jane Doe"')
if '20' not in output:
    raise AssertionError('Output should include age 20')
if 's1234' not in output_lower:
    raise AssertionError('Output should include student ID "S1234"')

